    // 1. Null checks take precedence
    if ((momentum_error_nms == NULL) || (field_body_t == NULL) || 
        (command == NULL) || (achievable_torque_nm == NULL)) {
        command->command = (adcs_vec3_t){0.0, 0.0, 0.0};
        command->saturated_axes = 0U;
        *achievable_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_NULL;
    }

    // 2. Validate finite values and non-negative limits/gains
    if ((!adcs_is_finite_vec3(momentum_error_nms)) || 
        (!adcs_is_finite_vec3(field_body_t)) || 
        (!isfinite(torque_gain_s_inv)) || 
        (!isfinite(max_dipole_a_m2)) || 
        (torque_gain_s_inv < 0.0) || 
        (max_dipole_a_m2 < 0.0)) {
        command->command = (adcs_vec3_t){0.0, 0.0, 0.0};
        command->saturated_axes = 0U;
        *achievable_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

    // 3. Check for degenerate magnetic field
    double b_norm_sq = adcs_vec3_dot(field_body_t, field_body_t);
    if (b_norm_sq <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        command->command = (adcs_vec3_t){0.0, 0.0, 0.0};
        command->saturated_axes = 0U;
        *achievable_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    // 4. Compute desired torque: tau_d = -gain * h_err
    adcs_vec3_t tau_d = adcs_vec3_scale(momentum_error_nms, -torque_gain_s_inv);

    // 5. Compute minimum-norm dipole: m = (B x tau_d) / ||B||^2
    adcs_vec3_t cross_temp = adcs_vec3_cross(field_body_t, &tau_d);
    adcs_vec3_t m = adcs_vec3_scale(&cross_temp, 1.0 / b_norm_sq);

    // 6. Apply norm saturation uniformly
    double m_norm = adcs_vec3_norm(&m);
    unint32 saturated_axes = 0U;
    if (m_norm > max_dipole_a_m2) {
        double scale_factor = max_dipole_a_m2 / m_norm;
        m = adcs_vec3_scale(&m, scale_factor);
        saturated_axes = 7U;
    }

    // 7. Set output command
    command->command = m;
    command->saturated_axes = saturated_axes;

    // 8. Compute physically achievable torque: tau = m x B
    *achievable_torque_nm = adcs_vec3_cross(&m, field_body_t);

    // 9. Return success
    return ADCS_OK;
}

